class IPhoneUe(LteUe):
    """iPhone Ue"""
    data_transfer_types = {
        'iperf': IphoneIperfDataTransfer,
        'ping': IphonePingDataTransfer,
        'ftp': IphoneFtpDataTransfer
    }

    def __init__(self, name, ue_id, configuration, rpc_client):
        """
        IPhoneUe constructor

        :param name: name of UE
        :param ue_id: UE identifier e.g. serial number
        :param configuration: configuration of UE
        :param rpc_client:
        """
        super().__init__(name, configuration)
        self.prepared = False
        self.ne_id = None
        self.ue_model = None
        if ue_id is None:
            self.ue_id = "no S/N"
        else:
            self.ue_id = ue_id
            self.rpc_client = rpc_client

        self.phone_number = self._configuration.get('phone_number')
        self._voice_call = None

        self._create_ue_identification()
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': self.ue_id})

    def _create_ue_identification(self):
        self.ne_id = UeIdentification(identifiers=[('iphonewaf2', self.ue_id)],
                                      network_elem_type='UE',
                                      specific_for_tool='iphonewaf2')

    def shutdown(self):
        self.logger.debug("executing shutdown")
        self.rpc_client.release_ue(ue_id=self.ue_id)

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        self.logger.debug("checking whether UE can be reserved on taf.ue.proxy")
        reserved_ues = self.rpc_client.get_reserved_ues().get("ue_ids", [])
        self.logger.debug(f"list of already reserved UEs on taf.ue.proxy: {reserved_ues}")
        if self.name in reserved_ues:
            raise UeAlreadyReserved(
                f"UE with serial number \"{self.ue_id}\" cannot be reserved, because is already reserved. "
                f"The reservation could be made manually or by previous Robot TC.\n"
                f"Before re-execution:\n"
                f"1) make sure that UE PC isn't used by other tester or Robot TC AND\n"
                f"2) repair the environment:\n"
                f"  a) restart taf.ue.proxy service OR\n"
                f"  b) release UE manually: open \"{self.rpc_client.remote_url}/docs\" -> open \"release_ue\" endpoint "
                f"-> button \"Try it out\" -> provide ue_id \"{self.ue_id}\" in request body -> button \"Execute\"")
        self.logger.debug("prepare_ue before calling reserve_ue on taf.ue.proxy")
        self.prepared = self.rpc_client.reserve_ue(ue_id=self.ue_id, ue_config={'phone_number': self.phone_number})
        self.logger.debug("prepare_ue after calling reserve_ue on taf.ue.proxy")
        self._log_ue_pc_diagnostic_info()
        return self.prepared

    def attach(self, timeout=-1, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform attach on UE.

        :param timeout: not supported
        :param validation: if True, check if detach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: not supported
        :return: None
        """
        self.logger.debug("executing attach")
        validation = strtobool(validation) if isinstance(validation, str) else validation
        response = self.rpc_client.attach_ue(ue_id=self.ue_id, extra_params={'validation': validation})
        self.log_ue_info(['serial', 'udid', 'airplane_mode_enabled', 'mobile_data_enabled', 'ips', 'cell_info'])
        print(response)
        self.logger.debug(f"attach response: {response}")

    def detach(self, timeout=-1, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform detach on UE.
        No action if UE is already detached.

        :param timeout: not supported
        :param validation: if True, check if detach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: not supported
        :return: None
        """
        self.logger.debug("executing detach")
        validation = strtobool(validation) if isinstance(validation, str) else validation
        response = self.rpc_client.detach_ue(ue_id=self.ue_id, extra_params={'validation': validation})
        print(response)
        self.logger.debug(f"detach response: {response}")

    def log_ue_info(self, info='ALL'):
        """

        :return: None
        """
        response = self.get_info(info)
        self.logger.debug(f"output from get_info: {response}")
        print(json.dumps(response, sort_keys=False, indent=4))

    def get_ue_info(self, info='ALL'):
        """
        :return: info
        """
        response = self.get_info(info)
        self.logger.debug(f"output from get_info: {response}")
        response = list(response.values())[0] if len(response) == 1 else response
        return response

    def get_info(self, info, timeout=None):
        """
        Return information about UE.
        """

        self.logger.debug(f"executing get_info with parameters {info}")
        if isinstance(info, str):
            wanted_attrs = [info.lower()]
        elif isinstance(info, list):
            wanted_attrs = [info_type.lower() for info_type in info if isinstance(info_type, str)]
        else:
            raise TypeError(f"`IphoneUe.get_info` - wrong `info` parameter type: {type(info)}.\n"
                            f"Allowed types: str, list")

        if 'all' in wanted_attrs:
            response = self.rpc_client.get_ue_info(ue_id=self.ue_id)
            return response

        response = self.rpc_client.get_ue_info(ue_id=self.ue_id, ue_attributes=wanted_attrs)
        return response

    def reboot_ue(self, timeout=180):
        """
        Reboot UE.
        :param timeout: waiting time in seconds for UE after reboot
        :return: None
        """
        self.logger.debug("executing reboot ue")
        self.rpc_client.reboot_ue(ue_id=self.ue_id, timeout=timeout)

