    def send_sms(self, phone_number, text):
        """
        Send sms.

        :return:
        """
        self.logger.debug("executing send SMS")
        ue_pool = aliases_registry()
        recognized_ues = \
            {self._validate_phone_number(ue_pool[ue]._configuration['phone_number']): ue_pool[ue].name
             for ue in ue_pool.keys() if isinstance(ue_pool[ue], IPhoneUe)}  # Dict -> {phone_number: ue_id}
        try:
            ue_id = recognized_ues[phone_number]
        except KeyError:
            raise UnrecognizedPhoneNumber(f"Phone number: {phone_number} is not recognized!\n"
                                          "Phone numbers defined in config:"
                                          f" {list(recognized_ues.keys())}")
        await_for_sms_thread = AwaitForSmsThread(target_function=self.rpc_client.await_for_sms,
                                                 target_kwargs={'ue_id': ue_id,
                                                                'expected_number': phone_number,
                                                                'timeout': '60s'})
        await_for_sms_thread.start()
        self.logger.debug(f"Name of UE sending SMS: {self.ue_id}")
        self.rpc_client.send_sms(ue_id=self.ue_id, phone_number=phone_number, text=text)
        await_for_sms_thread.join()
        if await_for_sms_thread.exception_queue:
            raise AwaitingForSmsException(await_for_sms_thread.exception_queue)
        self.log_ue_info(['serial', 'udid', 'airplane_mode_enabled', 'mobile_data_enabled', 'ips', 'cell_info'])

    def receive_sms(self, expected_number, expected_text, timeout):
        """
        Receive sms.

        :return:
        """
        self.logger.debug("executing receive SMS")
        response = self.rpc_client.receive_sms(ue_id=self.ue_id)
        self.log_ue_info(['serial', 'udid', 'airplane_mode_enabled', 'mobile_data_enabled', 'ips', 'cell_info'])
        self.logger.debug(f"Receive SMS response: {response}")
        if expected_text != response['text']:
            raise WrongSmsTextMessage("Expected SMS text: {}"
                                      "Actually received SMS text {}".format(expected_text, response['text']))
        elif self._validate_phone_number(expected_number) != self._validate_phone_number(response['number']):
            raise WrongSmsSender("Expected SMS from: {}\n"
                                 "Actually received from: {}".format(self._validate_phone_number(expected_number),
                                                                     self._validate_phone_number(response['number'])))

